import sqlite3
from fastapi import Depends, FastAPI, HTTPException
from pydantic import BaseModel, Field

app = FastAPI()

def criar_tabela():
    con = sqlite3.connect("tarefas.db")
    con.execute("""CREATE TABLE IF NOT EXISTS tarefas (
        id INTEGER PRIMARY KEY,
        titulo TEXT NOT NULL,
        feita INTEGER NOT NULL DEFAULT 0)""")
    con.commit()
    con.close()

criar_tabela()

def banco():
    con = sqlite3.connect("tarefas.db")
    con.row_factory = sqlite3.Row
    try:
        yield con
    finally:
        con.close()

class NovaTarefa(BaseModel):
    titulo: str = Field(min_length=3, max_length=120)

@app.get("/tarefas")
def listar(con: sqlite3.Connection = Depends(banco)):
    linhas = con.execute("SELECT id, titulo, feita FROM tarefas ORDER BY id").fetchall()
    return [{"id": l["id"], "titulo": l["titulo"], "feita": bool(l["feita"])} for l in linhas]

@app.post("/tarefas", status_code=201)
def criar(nova: NovaTarefa, con: sqlite3.Connection = Depends(banco)):
    cursor = con.execute("INSERT INTO tarefas (titulo) VALUES (?)", (nova.titulo.strip(),))
    con.commit()          # sem commit, nada é gravado
    return {"id": cursor.lastrowid, "titulo": nova.titulo.strip(), "feita": False}

@app.get("/tarefas/{id}")
def uma(id: int, con: sqlite3.Connection = Depends(banco)):
    linha = con.execute("SELECT id, titulo, feita FROM tarefas WHERE id = ?", (id,)).fetchone()
    if linha is None:
        raise HTTPException(status_code=404, detail="tarefa não encontrada")
    return {"id": linha["id"], "titulo": linha["titulo"], "feita": bool(linha["feita"])}

