import sqlite3
from flask import Flask, abort, g, request

app = Flask(__name__)
ARQUIVO = "tarefas.db"

def banco():
    if "banco" not in g:
        g.banco = sqlite3.connect(ARQUIVO)
        g.banco.row_factory = sqlite3.Row
    return g.banco

@app.teardown_appcontext
def fechar(erro):
    con = g.pop("banco", None)
    if con is not None:
        con.close()

with app.app_context():
    banco().execute("""CREATE TABLE IF NOT EXISTS tarefas (
        id INTEGER PRIMARY KEY,
        titulo TEXT NOT NULL,
        feita INTEGER NOT NULL DEFAULT 0)""")
    banco().commit()

@app.get("/tarefas")
def listar():
    linhas = banco().execute("SELECT id, titulo, feita FROM tarefas ORDER BY id").fetchall()
    return [{"id": l["id"], "titulo": l["titulo"], "feita": bool(l["feita"])} for l in linhas]

@app.post("/tarefas")
def criar():
    dado = request.get_json(silent=True) or {}
    titulo = dado.get("titulo", "")
    if not isinstance(titulo, str) or not 3 <= len(titulo.strip()) <= 120:
        return {"erro": "dados inválidos", "campos": ["titulo"]}, 400

    con = banco()
    cursor = con.execute("INSERT INTO tarefas (titulo) VALUES (?)", (titulo.strip(),))
    con.commit()
    return {"id": cursor.lastrowid, "titulo": titulo.strip(), "feita": False}, 201

@app.get("/tarefas/<int:id>")
def uma(id):
    linha = banco().execute("SELECT id, titulo, feita FROM tarefas WHERE id = ?", (id,)).fetchone()
    if linha is None:
        abort(404)
    return {"id": linha["id"], "titulo": linha["titulo"], "feita": bool(linha["feita"])}

