const express = require("express");
const { DatabaseSync } = require("node:sqlite");

const app = express();
app.use(express.json());

const banco = new DatabaseSync("tarefas.db");
banco.exec(`CREATE TABLE IF NOT EXISTS tarefas (
  id INTEGER PRIMARY KEY,
  titulo TEXT NOT NULL,
  feita INTEGER NOT NULL DEFAULT 0)`);

const emTarefa = (l) => ({ id: l.id, titulo: l.titulo, feita: Boolean(l.feita) });

app.get("/tarefas", (req, res) => {
  const linhas = banco.prepare("SELECT id, titulo, feita FROM tarefas ORDER BY id").all();
  res.json(linhas.map(emTarefa));
});

app.post("/tarefas", (req, res) => {
  const titulo = req.body?.titulo;
  if (typeof titulo !== "string" || titulo.trim().length < 3) {
    return res.status(400).json({ erro: "dados inválidos", campos: ["titulo"] });
  }
  const r = banco.prepare("INSERT INTO tarefas (titulo) VALUES (?)").run(titulo.trim());
  res.status(201).json({ id: Number(r.lastInsertRowid), titulo: titulo.trim(), feita: false });
});

app.get("/tarefas/:id", (req, res) => {
  const linha = banco
    .prepare("SELECT id, titulo, feita FROM tarefas WHERE id = ?")
    .get(Number(req.params.id));
  if (!linha) return res.status(404).json({ erro: "tarefa não encontrada" });
  res.json(emTarefa(linha));
});

app.listen(3000);

