// tarefas/repositorio.js, o ÚNICO arquivo que mudou
const { DatabaseSync } = require("node:sqlite");

const banco = new DatabaseSync("tarefas.db");

banco.exec(`CREATE TABLE IF NOT EXISTS tarefas (
  id INTEGER PRIMARY KEY, titulo TEXT NOT NULL, feita INTEGER NOT NULL DEFAULT 0)`);

const emTarefa = (l) => (l ? { id: l.id, titulo: l.titulo, feita: Boolean(l.feita) } : null);

const listar = () =>
  banco.prepare("SELECT id, titulo, feita FROM tarefas ORDER BY id").all().map(emTarefa);

function salvar(tarefa) {
  const r = banco
    .prepare("INSERT INTO tarefas (titulo, feita) VALUES (?, ?)")
    .run(tarefa.titulo, tarefa.feita ? 1 : 0);
  return { ...tarefa, id: Number(r.lastInsertRowid) };
}

const porId = (id) =>
  emTarefa(banco.prepare("SELECT id, titulo, feita FROM tarefas WHERE id = ?").get(id));

module.exports = { listar, salvar, porId };

